#!/bin/sh
# Re-embed provenance into every shipped homepage raster.
I=.claude/skills/impeccable/scripts/impeccable
R="Runway generate_image nano-banana-pro; reference = approved comp task 45492061-85f2-41b0-b307-24e44e938871."
$I embed-prompt .impeccable/build/masters/lead-tarp.png --prompt "$R Prompt: Recreate only the large white glossy vinyl tarp at the top left of @comp as a clean production image asset, seen straight on, filling the whole frame edge to edge. Keep its exact material: white vinyl with soft natural folds and glossy highlights, a thin indigo-black hem strip along the top edge, brass grommets evenly spaced along the top and bottom edges. Make it completely blank: remove the printed name lettering, the print-head rail and carriage, the text field and the button. No text anywhere, no wall around it, no border. (Runway task b9fa6515-6dba-4f80-8f7c-7a9e9b349c22; resized and edge-trimmed.)"
$I embed-prompt .impeccable/build/masters/arena-tarp.png --prompt "$R Prompt: Recreate only the large black glossy vinyl tarp at the lower left of @comp as a clean production image asset, seen straight on, filling the whole frame edge to edge. Keep its exact material: glossy black vinyl with soft folds, a crimson-and-black checkerboard band along the top edge and another along the bottom edge, brass grommets evenly spaced along both edges. Make it completely blank in the middle: remove all lettering and the brush underline. No text anywhere, no wall around it, no border. (Runway task 351e8e5a-25b6-497b-8270-f7797b323cee; resized and edge-trimmed.)"
$I embed-prompt .impeccable/build/masters/ledger-tarp.png --prompt "$R Prompt: Recreate only the deep crimson vinyl tarp at the top right of @comp as a clean production image asset, seen straight on, filling the whole frame edge to edge. Keep its exact material: deep crimson glossy vinyl printed all over with a darker crimson hemp-leaf geometric pattern, soft folds and highlights, brass grommets at the four corners. Make it completely blank: remove all lettering. No text anywhere, no wall around it, no border. (Runway task 60423d79-9e03-4feb-8abe-1f68a980f188; resized and edge-trimmed.)"
$I embed-prompt .impeccable/build/masters/insight-tarp.png --prompt "$R Prompt: Recreate only the flame orange vinyl tarp on the right side of @comp as a clean production image asset, seen straight on, filling the whole frame edge to edge. Keep its exact material: flame orange glossy vinyl with loose black ink brush swirls around its edges, soft folds and highlights, brass grommets at the four corners. Keep the centre calm and clear of swirls so text can sit there. Remove all lettering. No text anywhere, no wall around it, no border. (Runway task 105491c8-b616-40d5-840c-6cd41fb31a1b; resized and edge-trimmed.)"
FP="$R Prompt: Recreate only the indigo-violet vinyl tarp at the bottom right of @comp as a complete clean production image asset, seen straight on, filling the whole frame edge to edge, showing the whole tarp including its bottom edge. Keep its exact material: deep indigo-violet glossy vinyl with soft folds and highlights, brass grommets at the four corners. Make it completely blank: remove all lettering. No text anywhere, no wall around it, no border. (Runway task 1c46c970-bdf4-4eb0-a930-56c82d58228b"
$I embed-prompt .impeccable/build/masters/form-tarp-full.png --prompt "$FP; resized and edge-trimmed.)"
$I embed-prompt .impeccable/build/masters/form-tarp.png --prompt "$FP; top crop matching the comp region cut by the fold, edge-trimmed. Spec reference only.)"
PH="$R Prompt: Recreate only the print-head rail and carriage from the top of the white tarp in @comp, isolated on a plain flat mid-grey studio background: a long, thin horizontal brushed-steel rail with two parallel grooves running nearly the full width of the image, and a compact black carriage block with a crimson top mount sitting on the rail at the centre, seen straight on, product-photo lighting. Nothing else: no tarp, no lettering, no wall. (Runway task 7f0fbd91-7e12-4a12-8e79-ce1e03c88519; grey background removed locally with a colour-distance mask"
$I embed-prompt .impeccable/build/masters/print-head.png --prompt "$PH.)"
$I embed-prompt .impeccable/build/masters/print-rail.png --prompt "$PH; carriage removed and the rail gap filled with adjacent rail columns.)"
$I embed-prompt .impeccable/build/masters/print-carriage.png --prompt "$PH; carriage columns cropped out of the cut-out.)"
$I embed-prompt .impeccable/build/masters/wall.png --prompt "Origin: clean 44x60 patch of the approved comp's wall ground (region wall), mirror-tiled 2x2 and scaled to 176x240."
